// ─── Firebase Storage Layer ───────────────────────────────────────────────────
// All data lives in a single Firestore document: collection "app", document "main"
// This makes reads/writes simple and keeps the structure identical to the original.

const EMPTY_DB = () => ({
  spocs:{}, centres:{}, participants:{}, payments:{},
  cutoffDate:null, instructions:"", centreStatuses:{}, attendanceEnabled:false,
  nextCentreInternalId: 1,
  adminPassHash: null,  // null means fallback to hardcoded ADMIN_PASSWORD
});

const docRef = () => doc(db, "app", DB_DOC);

const loadDB = async () => {
  try {
    const snap = await getDoc(docRef());
    if (snap.exists()) return snap.data();
  } catch(e) { console.error("Firebase load error:", e); }
  return EMPTY_DB();
};

const saveDB = async (data) => {
  try {
    await setDoc(docRef(), data, { merge: false });
  } catch(e) { console.error("Firebase save error:", e); }
};

// Subscribe to real-time updates
const subscribeDB = (callback) => {
  return onSnapshot(docRef(), (snap) => {
    if (snap.exists()) callback(snap.data());
    else callback(EMPTY_DB());
  }, (err) => console.error("Firebase listen error:", err));
};

