const importParticipantsExcel = (e, existingParts, setParts, toast$) => {
  const file = e.target.files?.[0];
  e.target.value = "";
  if (!file) return;
  if (!window.XLSX) { toast$("XLSX library not loaded. Please try again.", "error"); return; }

  const reader = new FileReader();
  reader.onload = (ev) => {
    try {
      const wb   = window.XLSX.read(ev.target.result, { type: "binary" });
      const ws   = wb.Sheets[wb.SheetNames[0]];
      const rows = window.XLSX.utils.sheet_to_json(ws, { header: 1, defval: "" });
      if (rows.length < 2) { toast$("The file appears to be empty.", "error"); return; }

      // Find header row (contains "name")
      let headerIdx = 0;
      for (let i = 0; i < Math.min(5, rows.length); i++) {
        const r = rows[i].map(c => String(c).toLowerCase());
        if (r.some(c => c.includes("name"))) { headerIdx = i; break; }
      }
      const headers = rows[headerIdx].map(c => String(c).toLowerCase().trim());

      const col = (...keys) => { for (const k of keys) { const i = headers.findIndex(h => h.includes(k)); if (i !== -1) return i; } return -1; };
      const iTitle = col("title");
      const iName  = col("full name", "name");
      const iAge   = col("age");
      const iLang  = col("language", "lang");

      if (iName === -1) { toast$("Could not find a Name column. Use the provided template.", "error"); return; }

      const VALID_TITLES = ["Mr.", "Ms.", "Dr.", "Pr.", "Rev.", "Master", "Miss"];
      const VALID_LANGS  = ["Tamil", "English", "Hindi"];

      const imported = [];
      const skipped  = [];
      for (let i = headerIdx + 1; i < rows.length; i++) {
        const row = rows[i];
        const rawName = String(row[iName] || "").trim();
        if (!rawName) continue;

        // Normalise title
        let title = iTitle !== -1 ? String(row[iTitle] || "").trim() : "";
        if (title && !title.endsWith(".") && !["Master","Miss"].includes(title)) title += ".";
        if (!VALID_TITLES.includes(title)) title = "";

        // Age
        const rawAge = iAge !== -1 ? Number(row[iAge]) : NaN;
        const age = (!isNaN(rawAge) && rawAge >= 1 && rawAge <= 120) ? String(Math.round(rawAge)) : "";

        // Language
        let lang = "";
        if (iLang !== -1) {
          const rawL = String(row[iLang] || "").trim();
          const match = VALID_LANGS.find(l => l.toLowerCase() === rawL.toLowerCase());
          if (match) lang = match;
        }

        if (!title || !age || !lang) {
          skipped.push(`Row ${i + 1}: ${rawName}`);
        }

        imported.push({ id: uid(), title, name: rawName, age, language: lang,
          marks: "", rank: "", regNo: "", present: false, absent: false });
      }

      if (imported.length === 0) { toast$("No valid participant rows found.", "error"); return; }

      // Deduplicate against existing
      const existingNames = new Set(existingParts.filter(p => p.name).map(p => p.name.trim().toLowerCase()));
      const fresh = imported.filter(p => !existingNames.has(p.name.toLowerCase()));
      const dupes = imported.length - fresh.length;

      // Replace lone blank placeholder row
      const base = (existingParts.length === 1 && !existingParts[0].name) ? [] : existingParts;
      setParts([...base, ...fresh]);

      const msgs = [`Imported ${fresh.length} participant${fresh.length!==1?"s":""}.`];
      if (dupes)          msgs.push(`${dupes} duplicate${dupes!==1?"s":""} skipped.`);
      if (skipped.length) msgs.push(`${skipped.length} row${skipped.length!==1?"s":""} had missing fields — fill them manually.`);
      toast$(msgs.join(" "), skipped.length || dupes ? "warn" : "success");
    } catch (err) {
      console.error("Import error:", err);
      toast$("Failed to read the file. Make sure it is a valid .xlsx or .csv.", "error");
    }
  };
  reader.readAsBinaryString(file);
};


// ─── Toast ────────────────────────────────────────────────────────────────────
function Toast({ msg, type, onClose }) {
  useEffect(()=>{ if(msg){ const t=setTimeout(onClose,4000); return()=>clearTimeout(t); } },[msg]);
  if (!msg) return null;
  const colors={success:"#059669",error:"#dc2626",info:"#0ea5e9",warn:"#d97706"};
  return (
    <div style={{position:"fixed",bottom:24,left:"50%",transform:"translateX(-50%)",
      background:colors[type]||colors.info,color:"#fff",padding:"12px 28px",borderRadius:28,
      fontWeight:700,fontSize:14,zIndex:9999,boxShadow:"0 8px 32px #0008",
      animation:"slideUp .2s ease",whiteSpace:"nowrap",maxWidth:"90vw",textAlign:"center"}}>
      {msg}
    </div>
  );
}

