function CutoffBanner({ cutoffDate }) {
  if (!cutoffDate) return null;
  const passed=isCutoff(cutoffDate);
  const dt=new Date(cutoffDate).toLocaleDateString("en-IN",{day:"numeric",month:"long",year:"numeric"});
  return (
    <div style={{background:passed?"#fee2e2":"#d1fae5",borderRadius:10,padding:"10px 16px",marginBottom:20,
      fontSize:13,color:passed?"#991b1b":"#065f46",fontWeight:500}}>
      {passed?`⛔ Registration closed on ${dt}.`:`⏳ Registration closes on ${dt}.`}
    </div>
  );
}

