// APP ROOT
// ══════════════════════════════════════════════════════════════════════════════
export default function App() {
  const [db,      setDb]      = useState(null);
  const [online,  setOnline]  = useState(true);
  const [view,    setView]    = useState("login");
  const [session, setSession] = useState(null);
  const [toast,   setToast]   = useState({msg:"",type:"info"});

  useEffect(()=>{
    // Load XLSX
    const s=document.createElement("script");
    s.src="https://cdnjs.cloudflare.com/ajax/libs/xlsx/0.18.5/xlsx.full.min.js";
    document.head.appendChild(s);

    // Subscribe to Firestore real-time updates
    const unsub = subscribeDB((data) => {
      setDb(data);
      setOnline(true);
    });

    // Online/offline detection
    const goOnline  = () => setOnline(true);
    const goOffline = () => setOnline(false);
    window.addEventListener("online",  goOnline);
    window.addEventListener("offline", goOffline);

    return () => {
      unsub();
      window.removeEventListener("online",  goOnline);
      window.removeEventListener("offline", goOffline);
    };
  },[]);

  // persist: saves to Firestore, UI updates instantly via onSnapshot
  const persist = useCallback(async(nd)=>{
    setDb(nd);          // optimistic local update
    await saveDB(nd);   // write to Firestore
  },[]);

  const toast$ = (msg,type="info") => setToast({msg,type});
  const logout  = () => { setSession(null); setView("login"); };

  if (!db) return (
    <div style={{minHeight:"100vh",background:"#f8f9fb",display:"flex",flexDirection:"column",alignItems:"center",justifyContent:"center",gap:16}}>
      <style>{GLOBAL_CSS}</style>
      <div style={{width:36,height:36,border:"3px solid #1e3a5f",borderTopColor:"#b8960c",borderRadius:"50%",animation:"spin .7s linear infinite"}}/>
      <div style={{fontSize:13,color:"#475569"}}>Connecting to database…</div>
    </div>
  );

  return (
    <>
      <style>{GLOBAL_CSS}</style>
      {/* Online status indicator */}
      {!online && (
        <div style={{position:"fixed",top:0,left:0,right:0,zIndex:9999,background:"#dc2626",
          color:"#fff",textAlign:"center",padding:"8px",fontSize:13,fontWeight:600}}>
          ⚠️ You are offline. Changes will sync when connection is restored.
        </div>
      )}
      {view==="login"    && <LoginView    db={db} persist={persist} setSession={setSession} setView={setView} toast$={toast$} online={online} />}
      {view==="register" && <RegisterView db={db} persist={persist} setView={setView} toast$={toast$} />}
      {view==="forgot"   && <ForgotView   db={db} setView={setView} />}
      {view==="spoc"     && session && <SpocPortal db={db} persist={persist} session={session} logout={logout} toast$={toast$} />}
      {view==="admin"    && <AdminDash   db={db} persist={persist} logout={logout} toast$={toast$} />}
      <Toast msg={toast.msg} type={toast.type} onClose={()=>setToast({msg:""})} />
    </>
  );
}

