// FORGOT PASSWORD
// ══════════════════════════════════════════════════════════════════════════════
function ForgotView({ db, setView }) {
  const [email,setEmail]=useState("");
  const [submitted,setSubmitted]=useState(false);
  const [results,setResults]=useState([]);
  const isDesktop=useDesktop();

  const lookup=()=>{
    const e=email.trim().toLowerCase();
    if(!e||!/\S+@\S+\.\S+/.test(e)){return;}
    const matched=Object.values(db.spocs||{}).filter(s=>s.email?.toLowerCase()===e);
    setResults(matched);
    setSubmitted(true);
  };

  return (
    <div style={{minHeight:"100vh",background:"var(--bg)",display:"flex",flexDirection:"column"}}>
      <div style={{background:"var(--surface)",borderBottom:"1px solid var(--border)",padding:"13px 20px",
        display:"flex",alignItems:"center",justifyContent:"space-between"}}>
        <div style={{display:"flex",alignItems:"center",gap:8}}>
          <img src={IMG_EN} alt="BTH" style={{height:30,borderRadius:5,objectFit:"cover"}} />
          <img src={IMG_TM} alt="முத்தெடுக்க வா" style={{height:30,borderRadius:5,objectFit:"cover"}} />
        </div>
        <button className="btn btn-ghost btn-sm" onClick={()=>setView("login")}>← Back to Login</button>
      </div>
      <div style={{flex:1,display:"flex",alignItems:"center",justifyContent:"center",padding:"32px 18px"}}>
        <div style={{width:"100%",maxWidth:460}}>
          <div className="page-title">Forgot Username</div>
          <div className="page-sub">Enter the email address linked to your account and we'll show the usernames registered to it.</div>
          <SectionCard>
            <Field label="Email Address" style={{marginBottom:16}}>
              <input className="inp" type="email" placeholder="you@example.com"
                value={email} onChange={e=>{setEmail(e.target.value);setSubmitted(false);}}
                onKeyDown={e=>e.key==="Enter"&&lookup()} />
            </Field>
            <button className="btn btn-gold btn-full" onClick={lookup}>Look Up My Account</button>
          </SectionCard>

          {submitted && (
            results.length===0
              ? <div style={{background:"#fee2e2",border:"1px solid #fca5a5",borderRadius:12,padding:"16px 18px",
                  fontSize:13,color:"#991b1b",fontWeight:500}}>
                  No accounts found linked to <strong>{email}</strong>. Please check the email or create a new account.
                </div>
              : <>
                  <div style={{fontSize:13,color:"var(--muted)",marginBottom:12,fontWeight:600}}>
                    Found {results.length} account{results.length!==1?"s":""} linked to <strong style={{color:"var(--text)"}}>{email}</strong>:
                  </div>
                  {results.map(s=>(
                    <SectionCard key={s.id} style={{marginBottom:12}}>
                      <div style={{display:"flex",alignItems:"center",justifyContent:"space-between",flexWrap:"wrap",gap:8}}>
                        <div>
                          <div style={{fontWeight:700,fontSize:15,marginBottom:4}}>👤 {s.name||s.username}</div>
                          <div style={{fontSize:13,color:"var(--muted)",marginBottom:4}}>
                            Username: <span style={{fontWeight:700,color:"var(--text)",fontFamily:"monospace"}}>{s.username}</span>
                          </div>
                          {s.mobile&&<div style={{fontSize:12,color:"var(--subtle)"}}>📱 {s.mobile}</div>}
                        </div>
                        <button className="btn btn-gold btn-sm" onClick={()=>setView("login")}>Sign In →</button>
                      </div>
                    </SectionCard>
                  ))}
                  <div style={{background:"#fef3c7",border:"1px solid #d4af37",borderRadius:10,padding:"10px 14px",
                    fontSize:12,color:"#7d6608",marginTop:4}}>
                    ⚠️ Passwords cannot be recovered as they are stored securely. If you cannot remember your password, please contact the admin to reset it.
                  </div>
                </>
          )}
        </div>
      </div>
    </div>
  );
}

