// REGISTER
// ══════════════════════════════════════════════════════════════════════════════
function RegisterView({ db, persist, setView, toast$ }) {
  const [f,setF]=useState({username:"",password:"",confirm:"",name:"",mobile:"",email:""});
  const [err,setErr]=useState({});
  const isDesktop=useDesktop();
  const upd=(k,v)=>{setF(p=>({...p,[k]:v}));setErr(e=>{const n={...e};delete n[k];return n;});};

  const submit=async()=>{
    const e={};
    if(!f.name.trim())                                   e.name="Required";
    if(!f.mobile.trim()||!/^\d{10}$/.test(f.mobile))    e.mobile="Enter a valid 10-digit mobile number";
    if(!f.email.trim()||!/\S+@\S+\.\S+/.test(f.email))  e.email="Enter a valid email address";
    if(!f.username.trim()||f.username.trim().length<3)   e.username="Minimum 3 characters";
    if(!f.password||f.password.length<6)                 e.password="Minimum 6 characters";
    if(f.password!==f.confirm)                           e.confirm="Passwords do not match";
    if(Object.keys(e).length){setErr(e);return;}
    const uname=f.username.trim().toLowerCase();
    if(Object.values(db.spocs||{}).find(s=>s.username.toLowerCase()===uname)){setErr({username:"Username already taken"});return;}
    const spocId=uid();
    await persist({...db,
      spocs:{...db.spocs,[spocId]:{id:spocId,username:uname,passHash:hash(f.password),
        name:f.name.trim(),mobile:f.mobile.trim(),email:f.email.trim().toLowerCase()}}});
    toast$("Account created! Please log in.","success");
    setView("login");
  };

  return (
    <div style={{minHeight:"100vh",background:"var(--bg)",display:"flex",flexDirection:"column"}}>
      <div style={{background:"var(--surface)",borderBottom:"1px solid var(--border)",padding:"13px 20px",
        display:"flex",alignItems:"center",justifyContent:"space-between"}}>
        <div style={{display:"flex",alignItems:"center",gap:8}}>
          <img src={IMG_EN} alt="BTH" style={{height:30,borderRadius:5,objectFit:"cover"}} />
          <img src={IMG_TM} alt="முத்தெடுக்க வா" style={{height:30,borderRadius:5,objectFit:"cover"}} />
        </div>
        <button className="btn btn-ghost btn-sm" onClick={()=>setView("login")}>← Back to Login</button>
      </div>
      <div style={{flex:1,display:"flex",alignItems:isDesktop?"center":"flex-start",justifyContent:"center",padding:isDesktop?"40px":"20px 16px"}}>
        <div style={{width:"100%",maxWidth:isDesktop?680:"100%"}}>
          <div className="page-title">Create New User Account</div>
          <div className="page-sub">Set up your account to register and manage your centres</div>
          <div style={{display:isDesktop?"grid":"block",gridTemplateColumns:"1fr 1fr",gap:20}}>
            <SectionCard title="Personal Information">
              <Field label="Full Name *" error={err.name}>
                <input className={`inp${err.name?" err":""}`} placeholder="Your full name"
                  value={f.name} onChange={e=>upd("name",e.target.value)} />
              </Field>
              <Field label="Mobile Number *" error={err.mobile}>
                <input className={`inp${err.mobile?" err":""}`} placeholder="10-digit mobile number"
                  value={f.mobile} onChange={e=>upd("mobile",e.target.value)} maxLength={10} inputMode="tel" />
              </Field>
              <Field label="Email Address *" error={err.email} style={{marginBottom:0}}>
                <input className={`inp${err.email?" err":""}`} placeholder="you@example.com" type="email"
                  value={f.email} onChange={e=>upd("email",e.target.value)} autoCapitalize="none" />
              </Field>
            </SectionCard>
            <SectionCard title="Login Credentials">
              <Field label="Username *" error={err.username}>
                <input className={`inp${err.username?" err":""}`} placeholder="Choose a username (min 3 chars)"
                  value={f.username} onChange={e=>upd("username",e.target.value)} autoCapitalize="none" />
              </Field>
              <Field label="Password *" error={err.password}>
                <input className={`inp${err.password?" err":""}`} type="password" placeholder="Min 6 characters"
                  value={f.password} onChange={e=>upd("password",e.target.value)} />
              </Field>
              <Field label="Confirm Password *" error={err.confirm} style={{marginBottom:0}}>
                <input className={`inp${err.confirm?" err":""}`} type="password" placeholder="Re-enter password"
                  value={f.confirm} onChange={e=>upd("confirm",e.target.value)} />
              </Field>
            </SectionCard>
          </div>
          <button className="btn btn-gold" style={{marginTop:8,padding:"13px 32px",fontSize:15}} onClick={submit}>Create Account →</button>
        </div>
      </div>
    </div>
  );
}

