// SPOC PORTAL — Multi-centre
// ══════════════════════════════════════════════════════════════════════════════
function SpocPortal({ db, persist, session, logout, toast$ }) {
  const [activeCentreId, setActiveCentreId] = useState(null);
  const myCentres = Object.values(db.centres||{}).filter(c=>c.spocId===session.spocId||c.spocUsername===session.username);
  const spocInfo = Object.values(db.spocs||{}).find(s=>s.id===session.spocId||s.username===session.username)||{};

  const addCentre = async(name, code) => {
    const centreId = uid();
    // Always derive from actual max in use — prevents duplicates after deletions or imports
    const existingIds = Object.values(db.centres||{}).map(c=>Number(c.internalId)||0);
    const nextId = (existingIds.length ? Math.max(...existingIds) : 0) + 1;
    await persist({...db, nextCentreInternalId: nextId + 1,
      centres:{...db.centres,[centreId]:{id:centreId,internalId:nextId,name:name.trim(),code:code.trim(),spocUsername:session.username,spocId:session.spocId}}});
    toast$("Centre created!","success");
    setActiveCentreId(centreId);
  };

  if (activeCentreId === "__profile__") {
    return (
      <div style={{minHeight:"100vh",background:"var(--bg)"}}>
        <header style={{background:"var(--surface)",borderBottom:"1px solid var(--border)",padding:"13px 20px",
          display:"flex",alignItems:"center",justifyContent:"space-between",gap:12,position:"sticky",top:0,zIndex:50}}>
          <div style={{display:"flex",alignItems:"center",gap:8}}>
            <img src={IMG_EN} alt="BTH" style={{height:30,borderRadius:5,objectFit:"cover"}} />
            <img src={IMG_TM} alt="முத்தெடுக்க வா" style={{height:30,borderRadius:5,objectFit:"cover"}} />
          </div>
          <button className="btn btn-ghost btn-sm" onClick={()=>setActiveCentreId(null)}>← My Centres</button>
        </header>
        <main style={{maxWidth:600,margin:"0 auto",padding:"28px 16px"}}>
          <ProfileTab db={db} persist={persist} session={session} spocInfo={spocInfo} toast$={toast$} />
        </main>
      </div>
    );
  }

  if (activeCentreId) {
    const centre = db.centres?.[activeCentreId];
    if (!centre) { setActiveCentreId(null); return null; }
    return <SpocCentreView db={db} persist={persist} session={session} logout={logout} toast$={toast$}
      centre={centre} spocInfo={spocInfo} onBack={()=>setActiveCentreId(null)} />;
  }

  return <SpocHomeDash db={db} myCentres={myCentres} session={session} spocInfo={spocInfo} logout={logout}
    onSelectCentre={setActiveCentreId} onAddCentre={addCentre} toast$={toast$} />;
}

// ─── SPOC Home Dashboard (My Centres) ─────────────────────────────────────────
