function AttendanceExportPanel({ db, centres, attFrom, setAttFrom, attTo, setAttTo }) {
  const isDesktop=useDesktop();
  const [markSheet, setMarkSheet]=useState(false);

  // All centres sorted by code, only those with participants
  const allSorted = [...centres]
    .filter(c=>(db.participants?.[c.id]||[]).length>0)
    .sort((a,b)=>(a.code||"").localeCompare(b.code||""));

  const fromNum = parseInt(attFrom)||1;
  const toNum   = parseInt(attTo)||allSorted.length;
  const selected = allSorted.slice(fromNum-1, toNum);

  const exportAll   = () => printAllAttendanceSheets(allSorted, db, markSheet);
  const exportRange = () => { if(!selected.length) return; printAllAttendanceSheets(selected, db, markSheet); };

  return (
    <>
      <div style={{display:"flex",alignItems:"center",justifyContent:"space-between",marginBottom:16,flexWrap:"wrap",gap:10}}>
        <div>
          <div className="page-title" style={{marginBottom:2}}>{markSheet?"Mark Sheet Export":"Attendance Sheet Export"}</div>
          <div className="page-sub" style={{marginBottom:0}}>Each centre is exported as its own section in a single printable PDF, sorted by centre code.</div>
        </div>
        {/* Mode toggle */}
        <div style={{display:"flex",alignItems:"center",gap:10,background:"var(--surface)",border:"1px solid var(--border)",borderRadius:12,padding:"8px 14px",flexShrink:0}}>
          <span style={{fontSize:12,fontWeight:700,color:!markSheet?"var(--text)":"var(--muted)"}}>✍️ Attendance</span>
          <button onClick={()=>setMarkSheet(m=>!m)}
            style={{width:48,height:26,borderRadius:13,border:"none",cursor:"pointer",transition:"all .2s",
              background:markSheet?"#2563eb":"#cbd5e1",position:"relative",flexShrink:0}}>
            <span style={{position:"absolute",top:3,left:markSheet?24:3,width:20,height:20,
              borderRadius:"50%",background:"#fff",transition:"all .2s",boxShadow:"0 1px 3px #0003"}} />
          </button>
          <span style={{fontSize:12,fontWeight:700,color:markSheet?"#2563eb":"var(--muted)"}}>🏅 Marks</span>
        </div>
      </div>

      {markSheet&&(
        <div style={{background:"#dbeafe",border:"1px solid #93c5fd",borderRadius:10,padding:"10px 16px",marginBottom:16,fontSize:13,color:"#1d4ed8",fontWeight:600}}>
          🏅 Mark Sheet mode — Signature column replaced with Marks &amp; Rank. Absentees will show "Absent" in both columns.
        </div>
      )}

      <SectionCard style={{marginBottom:18}}>
        <div style={{fontSize:13,fontWeight:700,color:"var(--text)",marginBottom:12}}>
          All centres with participants: <span style={{color:"var(--gold)"}}>{allSorted.length}</span>
        </div>
        {allSorted.length===0
          ? <div style={{color:"var(--subtle)",fontSize:13}}>No centres with participants found.</div>
          : <>
              <div style={{display:"flex",flexWrap:"wrap",gap:6,marginBottom:14,maxHeight:140,overflowY:"auto"}}>
                {allSorted.map((c,i)=>(
                  <span key={c.id} style={{background:"#f1f5f9",borderRadius:6,padding:"3px 8px",fontSize:11,fontWeight:600}}>
                    {i+1}. {c.code||"—"} – {c.name}
                  </span>
                ))}
              </div>
              <button className="btn btn-gold" onClick={exportAll}>
                🖨️ Export All ({allSorted.length} centres)
              </button>
            </>
        }
      </SectionCard>

      <SectionCard title="Export by Range">
        <div style={{fontSize:12,color:"var(--muted)",marginBottom:12}}>
          Enter the position range (1-based, sorted by centre code) to export a subset.
        </div>
        <div style={{display:"flex",gap:10,alignItems:"flex-end",flexWrap:"wrap",marginBottom:14}}>
          <Field label="From (position)" style={{marginBottom:0,flex:1,minWidth:100}}>
            <input className="inp" type="number" min={1} max={allSorted.length||1}
              placeholder="1" value={attFrom} onChange={e=>setAttFrom(e.target.value)} />
          </Field>
          <Field label="To (position)" style={{marginBottom:0,flex:1,minWidth:100}}>
            <input className="inp" type="number" min={1} max={allSorted.length||1}
              placeholder={String(allSorted.length||1)} value={attTo} onChange={e=>setAttTo(e.target.value)} />
          </Field>
          <button className="btn btn-gold" disabled={!selected.length} onClick={exportRange}
            style={{flexShrink:0,height:42}}>
            🖨️ Export {selected.length} centre{selected.length!==1?"s":""}
          </button>
        </div>
        {selected.length>0&&(
          <div style={{fontSize:12,color:"var(--muted)"}}>
            Will export: {selected.map((c,i)=>`${fromNum+i}. ${c.code||"—"}`).join(", ")}
          </div>
        )}
      </SectionCard>
    </>
  );
}

function printAllAttendanceSheets(centreList, db, markSheet=false) {
  if(!centreList.length) return;

  const CATS = ["Child","Youth","Middle-Aged","Seniors"];
  const LANGS = ["Tamil","English","Hindi"];
  const catOrder = (p) => { const c=getCategory(p.age); return CATS.indexOf(c)<0?99:CATS.indexOf(c); };
  const langOrder = (p) => { const i=LANGS.indexOf(p.language); return i<0?99:i; };
  const sortName = (p) => (p.name||"").replace(/^(Mr\.|Ms\.|Dr\.|Pr\.|Rev\.|Master\s|Miss\s)\s*/i,"").trim().toLowerCase();

  let allPages = "";
  let firstPage = true;

  centreList.forEach(centre => {
    const rawParts = (db.participants?.[centre.id]||[]).filter(p=>p.name);
    if(!rawParts.length) return;

    // Sort: category order → name (stripped of title) → language order
    const participants = [...rawParts].sort((a,b)=>{
      const cd=catOrder(a)-catOrder(b); if(cd!==0) return cd;
      const nd=sortName(a).localeCompare(sortName(b)); if(nd!==0) return nd;
      return langOrder(a)-langOrder(b);
    });

    const centreName = centre.name||"—";
    const centreCode = centre.code||"";
    const addr = [centre.addr1,centre.addr2,centre.addr3,centre.city,centre.state,centre.pincode].filter(Boolean).join(", ");
    const spocName = [centre.spocTitle,centre.spocName].filter(Boolean).join(" ")||"—";
    const spocPhone = centre.spocPhone||"—";

    // ── Cross-tab summary (all CATS × all LANGS always, no Other col) ─────────
    const crosstab = {};
    CATS.forEach(c => { crosstab[c]={}; LANGS.forEach(l=>{ crosstab[c][l]=0; }); });
    participants.forEach(p => {
      const cat = getCategory(p.age); if(!cat) return;
      const lang = LANGS.includes(p.language) ? p.language : null; if(!lang) return;
      crosstab[cat][lang] = (crosstab[cat][lang]||0) + 1;
    });
    const colTotals = {};
    LANGS.forEach(l => { colTotals[l] = CATS.reduce((s,c)=>s+(crosstab[c]?.[l]||0),0); });
    const grandTotal = LANGS.reduce((s,l)=>s+colTotals[l],0);
    const summaryRows = CATS.map(cat => {
      const row = crosstab[cat]||{};
      const rowTotal = LANGS.reduce((s,l)=>s+(row[l]||0),0);
      const cells = LANGS.map(l=>`<td style="text-align:center">${row[l]||0}</td>`).join("");
      return `<tr><td><strong>${cat}</strong></td>${cells}<td style="text-align:center;font-weight:700">${rowTotal}</td></tr>`;
    }).join("");
    const footerCells = LANGS.map(l=>`<td style="text-align:center;font-weight:700">${colTotals[l]}</td>`).join("");
    const summaryHtml = `
      <table class="summary-table">
        <thead>
          <tr>
            <th>Category</th>
            ${LANGS.map(l=>`<th style="text-align:center">${l}</th>`).join("")}
            <th style="text-align:center">Total</th>
          </tr>
        </thead>
        <tbody>
          ${summaryRows}
          <tr class="total-row">
            <td><strong>Total</strong></td>
            ${footerCells}
            <td style="text-align:center;font-weight:700">${grandTotal}</td>
          </tr>
        </tbody>
      </table>`;

    // ── Header HTML (shared across all pages of this centre) ────────────────
    const headerHtml = `
      <div class="header">
        <div class="header-logos">
          <img src="${IMG_EN}" class="logo" alt="BTH" />
          <div class="header-text">
            <div class="title">Muthedukava - Bible Treasure Hunt 2026</div>
            <div class="subtitle">${markSheet?"Mark Sheet":"Attendance Sheet"}</div>
            <div class="centre-info">
              <span class="centre-name">${centreName}${centreCode?` &nbsp;<span class="centre-code">${centreCode}</span>`:""}</span>
              ${addr?`<span class="addr">${addr}</span>`:""}
              <span>SPOC: ${spocName}&nbsp;&nbsp;|&nbsp;&nbsp;&#128241; ${spocPhone}</span>
            </div>
          </div>
          <img src="${IMG_TM}" class="logo" alt="முத்தெடுக்க வா" />
        </div>
      </div>`;

    const ROWS_PER_PAGE = 20;
    const totalPages = Math.max(1, Math.ceil(participants.length / ROWS_PER_PAGE));

    for(let pg=0; pg<totalPages; pg++){
      const slice = participants.slice(pg*ROWS_PER_PAGE, (pg+1)*ROWS_PER_PAGE);
      const rowsHtml = slice.map((p,i)=>{
        const isAbsent = !!p.absent;
        const lastCols = markSheet
          ? `<td class="mark-cell" style="${isAbsent?"color:#dc2626;font-weight:700;text-align:center":""}">${isAbsent?"Absent":p.marks||"—"}</td>
             <td class="mark-cell" style="${isAbsent?"color:#dc2626;font-weight:700;text-align:center":""}">${isAbsent?"Absent":p.rank||"—"}</td>`
          : `<td class="sig-cell"></td>`;
        return `
        <tr${isAbsent&&markSheet?' class="absent-row"':""}>
          <td>${pg*ROWS_PER_PAGE+i+1}</td>
          <td>${p.regNo||""}</td>
          <td>${(p.title||"")+" "+(p.name||"")}</td>
          <td>${getCategory(p.age)||"—"}</td>
          <td>${p.language||"—"}</td>
          ${lastCols}
        </tr>`;
      }).join("");

      const isBreak = !firstPage || pg>0;
      firstPage = false;

      // Show summary table only on the first page of each centre
      const summarySection = pg===0 ? `<div class="summary-section">${summaryHtml}</div>` : "";

      allPages += `
        <div class="page${isBreak?" page-break":""}">
          ${headerHtml}
          ${summarySection}
          <table class="main-table">
            <thead>
              <tr><th>#</th><th>Reg. No.</th><th>Name</th><th>Category</th><th>Language</th>${markSheet?"<th style='text-align:center'>Marks</th><th style='text-align:center'>Rank</th>":"<th>Signature</th>"}</tr>
            </thead>
            <tbody>${rowsHtml}</tbody>
          </table>
          <div class="footer">
            <strong>${centreCode||centreName}</strong>&nbsp;&nbsp;|&nbsp;&nbsp;Page ${pg+1} of ${totalPages}
          </div>
        </div>`;
    }
  });

  if(!allPages){ alert("No participants found in selected centres."); return; }

  const html = `<!DOCTYPE html>
<html><head><meta charset="utf-8">
<title>BTH 2026 ${markSheet?"Mark Sheets":"Attendance Sheets"}</title>
<style>
  * { box-sizing:border-box; margin:0; padding:0; }
  body { font-family:Arial,sans-serif; font-size:10.5px; color:#000; }
  .page { padding:10mm 13mm 20mm; min-height:297mm; position:relative; display:flex; flex-direction:column; }
  .page-break { page-break-before:always; }

  /* Header */
  .header { border-bottom:2px solid #1e3a5f; padding-bottom:5px; margin-bottom:4px; }
  .header-logos { display:flex; align-items:center; gap:8px; }
  .logo { height:46px; border-radius:5px; object-fit:cover; flex-shrink:0; }
  .header-text { flex:1; text-align:center; }
  .title { font-size:13px; font-weight:900; letter-spacing:.5px; text-transform:uppercase; color:#1e3a5f; }
  .subtitle { font-size:10.5px; font-weight:700; margin-top:2px; color:#444; }
  .centre-info { display:flex; flex-direction:column; gap:1px; margin-top:4px; font-size:10px; }
  .centre-name { font-size:12px; font-weight:800; color:#1e3a5f; }
  .centre-code { background:#dbeafe; color:#1d4ed8; padding:1px 6px; border-radius:4px; font-size:10px; font-weight:800; margin-left:4px; }
  .addr { color:#555; }

  /* Summary table */
  .summary-section { margin-bottom:3px; }
  .summary-table { width:auto; border-collapse:collapse; font-size:9.5px; }
  .summary-table th { background:#1e3a5f; color:#fff; padding:3px 9px; text-align:left; }
  .summary-table td { padding:2px 9px; border-bottom:1px solid #e2e8f0; }
  .summary-table .total-row td { background:#f1f5f9; border-top:1px solid #94a3b8; }

  /* Main participants table */
  .main-table { width:100%; border-collapse:collapse; margin-top:3px; }
  .main-table th { background:#1e3a5f; color:#fff; padding:5px 7px; text-align:left; font-size:10px; }
  .main-table td { padding:7px 7px; border-bottom:1px solid #e8ecf0; vertical-align:middle; line-height:1.2; font-size:10px; }
  .main-table tr:nth-child(even) td { background:#f8f9fb; }
  .sig-cell { min-width:90px; height:36px; }
  .mark-cell { text-align:center; font-weight:700; font-size:11px; min-width:50px; }
  .absent-row td { background:#fff0f0 !important; }

  /* Footer */
  .footer { position:absolute; bottom:7mm; left:13mm; right:13mm; display:flex; justify-content:space-between; font-size:9px; color:#555; border-top:1px solid #cbd5e1; padding-top:3px; }

  @media print {
    @page { size:A4 portrait; margin:0; }
    body { print-color-adjust:exact; -webkit-print-color-adjust:exact; }
  }
</style></head>
<body>${allPages}</body></html>`;

  const w = window.open("","_blank","width=960,height=750");
  if(w){ w.document.write(html); w.document.close(); setTimeout(()=>w.print(),800); }
}

// ══════════════════════════════════════════════════════════════════════════════
// FULL IMPORT PANEL — import centres + participants from spreadsheet
// ══════════════════════════════════════════════════════════════════════════════
function FullImportPanel({ db, persist, toast$ }) {
  const [drag,setDrag]=useState(false);
  const [preview,setPreview]=useState(null);  // array of centre objects to create/update
  const [importing,setImporting]=useState(false);
  const [result,setResult]=useState(null);
  const fileRef=useRef();

  // ── Column finder (case-insensitive partial match) ────────────────────────
  const col=(headers,...names)=>{
    for(const n of names){
      const i=headers.findIndex(h=>h.includes(n.toLowerCase()));
      if(i>=0) return i;
    }
    return -1;
  };

  // ── Parse uploaded file ───────────────────────────────────────────────────
  const parseFile=(file)=>{
    if(!file) return;
    const ext=file.name.split(".").pop().toLowerCase();
    const reader=new FileReader();
    reader.onload=(e)=>{
      try {
        let rows=[];
        if(ext==="csv"){
          rows=e.target.result.split("\n").map(r=>r.split(",").map(c=>c.replace(/^"|"$/g,"").trim()));
        } else {
          const data=new Uint8Array(e.target.result);
          const wb=window.XLSX.read(data,{type:"array"});
          rows=window.XLSX.utils.sheet_to_json(wb.Sheets[wb.SheetNames[0]],{header:1,defval:""});
        }
        if(rows.length<2){toast$("File is empty.","error");return;}
        processRows(rows);
      } catch(err){toast$("Parse error: "+err.message,"error");}
    };
    if(ext==="csv") reader.readAsText(file); else reader.readAsArrayBuffer(file);
  };

  // ── Process rows into preview ─────────────────────────────────────────────
  // Accepts the Export Excel format directly:
  // Int. ID | Centre Code | Centre Name | Addr1 | Addr2 | City | State | Pincode |
  // SPOC Username | SPOC Title | SPOC Name | SPOC Addr1..SPOC Email |
  // Pastor Title | Pastor | Pastor Phone | P# | Reg No. | Title | Name | Age | Language |
  // Marks | Rank | Total (INR) | Payment Ref | Pay Date
  const processRows=(rows)=>{
    const headers=rows[0].map(h=>String(h||"").toLowerCase().trim());
    const c=(...n)=>{ for(const name of n){ const i=headers.findIndex(h=>h.includes(name.toLowerCase())); if(i>=0)return i; } return -1; };

    const iIntId   = c("int. id","int id","internal centre id","internal id");
    const iCCode   = c("centre code","code");
    const iCName   = c("centre name","center name");
    const iAddr1   = c("addr1","address1");
    const iAddr2   = c("addr2","address2");
    const iCity    = c("city");
    const iState   = c("state");
    const iPincode = c("pincode","pin","zip");
    const iSUser   = c("spoc username","username");
    const iSTitle  = c("spoc title");
    const iSName   = c("spoc name");
    const iSAddr1  = c("spoc addr1","spoc address1");
    const iSAddr2  = c("spoc addr2","spoc address2");
    const iSCity   = c("spoc city");
    const iSState  = c("spoc state");
    const iSPin    = c("spoc pincode","spoc pin");
    const iSPhone  = c("spoc phone","spoc mobile");
    const iSEmail  = c("spoc email","email");
    const iSPass   = c("spoc password","password");
    const iPaTitle = c("pastor title");
    const iPaName  = c("pastor name","pastor");
    const iPaPhone = c("pastor phone","pastor mobile");
    const iPTitle  = (()=>{
      // First try explicit "participant title" substring match
      let i=headers.findIndex(h=>h.includes("participant title"));
      if(i>=0) return i;
      // Fallback: exact column header "title" only (avoid matching "spoc title", "pastor title")
      i=headers.findIndex(h=>h==="title");
      return i;
    })();
    const iPName   = (()=>{
      // First try explicit "participant name" substring match
      let i=headers.findIndex(h=>h.includes("participant name"));
      if(i>=0) return i;
      // Fallback: exact column header "name" only (avoid matching "centre name", "spoc name", etc.)
      i=headers.findIndex(h=>h==="name");
      return i;
    })();
    const iPAge    = c("age");
    const iPLang   = c("language");
    const iRegNo   = c("reg no","registration no");
    const iMarks   = c("marks","score");
    const iRank    = c("rank");
    const iPresent = c("present");
    const iAbsent  = c("absent");
    const iPayRef  = c("payment ref","pay ref");
    const iPayDate = c("pay date","payment date");

    const g=(row,i)=>i>=0?String(row[i]||"").trim():"";
    const centreMap={}, centreOrder=[];

    for(let r=1;r<rows.length;r++){
      const row=rows[r];
      if(row.every(v=>String(v||"").trim()==="")) continue;
      const intId=g(row,iIntId), ccode=g(row,iCCode).toUpperCase(), cname=g(row,iCName);
      const key=intId||ccode||cname;
      if(!key) continue;
      if(!centreMap[key]){
        centreOrder.push(key);
        centreMap[key]={
          intId, name:cname, code:ccode,
          addr1:g(row,iAddr1), addr2:g(row,iAddr2), city:g(row,iCity),
          state:g(row,iState), pincode:g(row,iPincode),
          username:g(row,iSUser).toLowerCase(), password:g(row,iSPass),
          spocTitle:g(row,iSTitle), spocName:g(row,iSName),
          spocAddr1:g(row,iSAddr1), spocAddr2:g(row,iSAddr2),
          spocCity:g(row,iSCity), spocState:g(row,iSState),
          spocPincode:g(row,iSPin), spocPhone:g(row,iSPhone), spocEmail:g(row,iSEmail),
          pastorTitle:g(row,iPaTitle), pastorName:g(row,iPaName), pastorPhone:g(row,iPaPhone),
          payRef:g(row,iPayRef), payDate:g(row,iPayDate),
          participants:[],
          existing:Object.values(db.centres||{}).find(ec=>
            (intId&&String(ec.internalId||"")===intId)||
            (ccode&&(ec.code||"").toUpperCase()===ccode)||
            (!intId&&!ccode&&(ec.name||"").toLowerCase()===cname.toLowerCase())
          )||null
        };
      }
      const cm=centreMap[key];
      if(!cm.name&&cname) cm.name=cname;
      if(!cm.code&&ccode) cm.code=ccode;
      if(!cm.addr1) cm.addr1=g(row,iAddr1);
      if(!cm.city) cm.city=g(row,iCity);
      if(!cm.spocName) cm.spocName=g(row,iSName);
      if(!cm.spocPhone) cm.spocPhone=g(row,iSPhone);
      if(!cm.pastorName) cm.pastorName=g(row,iPaName);
      if(!cm.username) cm.username=g(row,iSUser).toLowerCase();
      if(!cm.payRef) cm.payRef=g(row,iPayRef);
      if(!cm.payDate) cm.payDate=g(row,iPayDate);

      const pname=g(row,iPName);
      if(pname){
        const parseBool=(v)=>["y","yes","1","true","x"].includes(v.toLowerCase());
        const presentRaw=iPresent>=0?g(row,iPresent):"";
        const absentRaw=iAbsent>=0?g(row,iAbsent):"";
        cm.participants.push({
          regNo:g(row,iRegNo), title:g(row,iPTitle), name:pname,
          age:g(row,iPAge), language:g(row,iPLang),
          marks:iMarks>=0?g(row,iMarks):"", rank:iRank>=0?g(row,iRank):"",
          present:iPresent>=0?parseBool(presentRaw):null,
          absent:iAbsent>=0?parseBool(absentRaw):null,
        });
      }
    }

    const rows2=centreOrder.map(k=>centreMap[k]);
    if(!rows2.length){toast$("No valid rows found. Check column headers match the export file.","error");return;}
    setPreview(rows2); setResult(null);
  };

  // ── Apply import ──────────────────────────────────────────────────────────
  const applyImport=async()=>{
    if(!preview||!preview.length) return;
    setImporting(true);
    try {
      let newDb={...db,spocs:{...db.spocs},centres:{...db.centres},
        participants:{...db.participants},payments:{...db.payments},
        nextCentreInternalId:db.nextCentreInternalId||1};
      let created=0, updated=0, partTotal=0;

      for(const row of preview){
        let centreId, centreObj;
        if(row.existing){
          centreId=row.existing.id; centreObj={...row.existing};
          if(row.name)        centreObj.name=row.name;
          if(row.code)        centreObj.code=row.code.toUpperCase();
          if(row.addr1)       centreObj.addr1=row.addr1;
          if(row.addr2)       centreObj.addr2=row.addr2;
          if(row.city)        centreObj.city=row.city;
          if(row.state)       centreObj.state=row.state;
          if(row.pincode)     centreObj.pincode=row.pincode;
          if(row.pastorTitle) centreObj.pastorTitle=row.pastorTitle;
          if(row.pastorName)  centreObj.pastorName=row.pastorName;
          if(row.pastorPhone) centreObj.pastorPhone=row.pastorPhone;
          if(row.spocTitle)   centreObj.spocTitle=row.spocTitle;
          if(row.spocName)    centreObj.spocName=row.spocName;
          if(row.spocAddr1)   centreObj.spocAddr1=row.spocAddr1;
          if(row.spocAddr2)   centreObj.spocAddr2=row.spocAddr2;
          if(row.spocCity)    centreObj.spocCity=row.spocCity;
          if(row.spocState)   centreObj.spocState=row.spocState;
          if(row.spocPincode) centreObj.spocPincode=row.spocPincode;
          if(row.spocPhone)   centreObj.spocPhone=row.spocPhone;
          if(row.spocEmail)   centreObj.spocEmail=row.spocEmail;
          updated++;
        } else {
          centreId=uid();
          const internalId=row.intId?parseInt(row.intId):newDb.nextCentreInternalId;
          if(!row.intId) newDb.nextCentreInternalId=internalId+1;
          centreObj={id:centreId,internalId,name:row.name||"",code:(row.code||"").toUpperCase(),
            addr1:row.addr1||"",addr2:row.addr2||"",city:row.city||"",state:row.state||"",pincode:row.pincode||"",
            pastorTitle:row.pastorTitle||"",pastorName:row.pastorName||"",pastorPhone:row.pastorPhone||"",
            spocTitle:row.spocTitle||"",spocName:row.spocName||"",
            spocAddr1:row.spocAddr1||"",spocAddr2:row.spocAddr2||"",
            spocCity:row.spocCity||"",spocState:row.spocState||"",
            spocPincode:row.spocPincode||"",spocPhone:row.spocPhone||"",
            spocEmail:row.spocEmail||"",spocUsername:row.username||"",spocId:""};
          created++;
        }

        if(row.username){
          const es=Object.values(newDb.spocs).find(s=>s.username===row.username);
          if(es){
            const us={...es};
            if(row.spocName) us.name=row.spocName;
            if(row.spocPhone) us.mobile=row.spocPhone;
            if(row.spocEmail) us.email=row.spocEmail;
            if(row.password) us.passHash=hash(row.password);
            newDb.spocs={...newDb.spocs,[es.id]:us};
            centreObj.spocUsername=row.username; centreObj.spocId=es.id;
          } else {
            const spocId=uid();
            newDb.spocs={...newDb.spocs,[spocId]:{id:spocId,username:row.username,
              passHash:hash(row.password||"bth2026"),
              name:row.spocName||"",mobile:row.spocPhone||"",email:row.spocEmail||""}};
            centreObj.spocUsername=row.username; centreObj.spocId=spocId;
          }
        }

        newDb.centres={...newDb.centres,[centreId]:centreObj};

        if(row.payRef||row.payDate){
          const ep=newDb.payments[centreId]||{};
          newDb.payments={...newDb.payments,[centreId]:{
            refNo:row.payRef||ep.refNo||"", payDate:row.payDate||ep.payDate||""}};
        }

        if(row.participants.length>0){
          const existing=(newDb.participants[centreId]||[]).map(p=>({...p}));
          for(const np of row.participants){
            let match=null;
            if(np.regNo) match=existing.find(ep=>(ep.regNo||"").toLowerCase()===np.regNo.toLowerCase());
            if(!match) match=existing.find(ep=>ep.name.toLowerCase()===np.name.toLowerCase()&&(ep.title||"")===(np.title||""));
            if(match){
              if(np.age)       match.age=np.age;
              if(np.language)  match.language=np.language;
              if(np.marks!=="") match.marks=np.marks;
              if(np.rank!=="")  match.rank=np.rank;
              if(np.present!==null){ match.present=np.present; if(np.present) match.absent=false; }
              if(np.absent!==null){  match.absent=np.absent;   if(np.absent)  match.present=false; }
            } else {
              existing.push({...emptyP(),regNo:np.regNo,title:np.title,name:np.name,
                age:np.age,language:np.language,marks:np.marks||"",rank:np.rank||"",
                present:np.present===true,absent:np.absent===true});
            }
          }
          newDb.participants={...newDb.participants,[centreId]:reassignRegNos(existing,centreObj.code||"")};
          partTotal+=row.participants.length;
        }
      }

      await persist(newDb);
      setResult({created,updated,partTotal});
      setPreview(null);
      toast$(`Done! ${created} centres created, ${updated} updated, ${partTotal} participants imported.`,"success");
    } catch(err){ toast$("Import failed: "+err.message,"error"); }
    setImporting(false);
  };

  // ── Template download — identical columns to Export Excel ─────────────────
  const downloadTemplate=()=>{
    const hdrs=["Int. ID","Centre Code","Centre Name","Addr1","Addr2","City","State","Pincode",
      "SPOC Username","SPOC Title","SPOC Name","SPOC Addr1","SPOC Addr2","SPOC City","SPOC State","SPOC Pincode","SPOC Phone","SPOC Email",
      "Pastor Title","Pastor","Pastor Phone","P#","Reg No.","Title","Name","Age","Language",
      "Marks","Rank","Present","Absent","Total (INR)","Payment Ref","Pay Date"];
    const ex=["1","CHN","Chennai North Church","12 Main Road","","Chennai","Tamil Nadu","600001",
      "davidpeter","Mr.","David Peter","","","Chennai","Tamil Nadu","600001","9876543211","david@example.com",
      "Pr.","John Samuel","9876543210","1","CHN-001","Mr.","Samuel John P.","25","Tamil",
      "","","Y","","2500","",""];
    const ws=window.XLSX.utils.aoa_to_sheet([hdrs,ex]);
    const wb=window.XLSX.utils.book_new();
    window.XLSX.utils.book_append_sheet(wb,ws,"Import");
    window.XLSX.writeFile(wb,"BTH2026_Import_Template.xlsx");
  };


  // ── Drag & drop ───────────────────────────────────────────────────────────
  const onDrop=(e)=>{e.preventDefault();setDrag(false);const f=e.dataTransfer.files[0];if(f)parseFile(f);};

  return (
    <>
      <div className="page-title">Full Import</div>
      <div className="page-sub">Import centres and participants from a spreadsheet. Existing centres (matched by code or name) will be updated; new ones will be created.</div>

      {/* Template download */}
      <SectionCard style={{marginBottom:16}}>
        <div style={{display:"flex",alignItems:"center",justifyContent:"space-between",flexWrap:"wrap",gap:10}}>
          <div>
            <div style={{fontWeight:700,marginBottom:4}}>📄 Download Template</div>
            <div style={{fontSize:12,color:"var(--muted)"}}>Fill in this Excel file and upload it below. One row per participant; repeat centre info on each row.</div>
          </div>
          <button className="btn btn-teal btn-sm" onClick={downloadTemplate}>⬇️ Template.xlsx</button>
        </div>
      </SectionCard>

      {/* Column reference */}
      <SectionCard title="Supported Columns" style={{marginBottom:16}}>
        <div style={{display:"grid",gridTemplateColumns:"repeat(auto-fill,minmax(220px,1fr))",gap:4,fontSize:12}}>
          {[
            ["Centre Name","Centre name (required)"],
            ["Centre Code","Code prefix e.g. CHN"],
            ["Addr1 / Addr2","Centre address lines"],
            ["City / State / Pincode","Centre location"],
            ["Pastor Title / Name / Phone","Pastor details"],
            ["SPOC Title / Name","SPOC identity"],
            ["SPOC Addr1 / Addr2 / City / State / Pincode","SPOC address"],
            ["SPOC Phone / Email","SPOC contact"],
            ["SPOC Username","Login username (creates account)"],
            ["SPOC Password","Login password (default: bth2026)"],
            ["Title","Participant title"],
            ["Name","Participant name (required for participant)"],
            ["Age","Participant age"],
            ["Language","Tamil / English / Hindi"],
          ].map(([col,desc])=>(
            <div key={col} style={{display:"flex",gap:6,alignItems:"flex-start"}}>
              <span style={{background:"#f1f5f9",borderRadius:4,padding:"1px 6px",fontWeight:700,color:"#1e3a5f",flexShrink:0,fontSize:11}}>{col}</span>
              <span style={{color:"var(--muted)"}}>{desc}</span>
            </div>
          ))}
        </div>
      </SectionCard>

      {/* Drop zone */}
      {!preview && !result && (
        <div onDragOver={e=>{e.preventDefault();setDrag(true);}} onDragLeave={()=>setDrag(false)} onDrop={onDrop}
          style={{border:`2px dashed ${drag?"var(--gold)":"var(--border)"}`,borderRadius:14,padding:"40px 20px",
            textAlign:"center",cursor:"pointer",transition:"all .2s",background:drag?"#fefce8":"var(--surface)",marginBottom:16}}
          onClick={()=>fileRef.current?.click()}>
          <div style={{fontSize:40,marginBottom:10}}>📂</div>
          <div style={{fontWeight:700,marginBottom:4}}>Drop Excel / CSV here</div>
          <div style={{fontSize:13,color:"var(--muted)"}}>or click to browse</div>
          <input ref={fileRef} type="file" accept=".xlsx,.xls,.csv" style={{display:"none"}}
            onChange={e=>{const f=e.target.files?.[0];if(f)parseFile(f);e.target.value="";}} />
        </div>
      )}

      {/* Preview */}
      {preview && (
        <>
          <div style={{display:"flex",alignItems:"center",justifyContent:"space-between",marginBottom:12,flexWrap:"wrap",gap:8}}>
            <div style={{fontWeight:700,fontSize:15}}>
              Preview — {preview.length} centre{preview.length!==1?"s":""}, {preview.reduce((s,r)=>s+r.participants.length,0)} participants
            </div>
            <div style={{display:"flex",gap:8}}>
              <button className="btn btn-ghost btn-sm" onClick={()=>{setPreview(null);setResult(null);}}>✕ Cancel</button>
              <button className="btn btn-gold" onClick={applyImport} disabled={importing}>
                {importing?"Importing…":"✅ Apply Import"}
              </button>
            </div>
          </div>
          <SectionCard style={{padding:0,overflow:"hidden"}}>
            <table className="data-table" style={{fontSize:12}}>
              <thead>
                <tr>
                  <th>Centre</th><th>Code</th><th>City</th>
                  <th>SPOC</th><th>Username</th>
                  <th style={{textAlign:"center"}}>Participants</th>
                  <th style={{textAlign:"center"}}>Action</th>
                </tr>
              </thead>
              <tbody>
                {preview.map((row,i)=>(
                  <tr key={i}>
                    <td style={{fontWeight:600}}>{row.name||"—"}</td>
                    <td>{row.code?<span style={{background:"#dbeafe",color:"#1d4ed8",padding:"1px 7px",borderRadius:4,fontWeight:700,fontSize:11}}>{row.code}</span>:"—"}</td>
                    <td>{row.city||"—"}</td>
                    <td>{[row.spocTitle,row.spocName].filter(Boolean).join(" ")||"—"}</td>
                    <td style={{color:"var(--purple)",fontWeight:600}}>{row.username||"—"}</td>
                    <td style={{textAlign:"center"}}>{row.participants.length}</td>
                    <td style={{textAlign:"center"}}>
                      {row.existing
                        ? <span style={{color:"#d97706",fontWeight:700,fontSize:11}}>✏️ Update</span>
                        : <span style={{color:"#059669",fontWeight:700,fontSize:11}}>➕ Create</span>}
                    </td>
                  </tr>
                ))}
              </tbody>
            </table>
          </SectionCard>
          {/* Participant detail */}
          {preview.some(r=>r.participants.length>0)&&(
            <details style={{marginTop:12}}>
              <summary style={{cursor:"pointer",fontWeight:600,fontSize:13,color:"var(--muted)",padding:"6px 0"}}>
                Show all participants ({preview.reduce((s,r)=>s+r.participants.length,0)})
              </summary>
              <SectionCard style={{padding:0,overflow:"hidden",marginTop:8}}>
                <table className="data-table" style={{fontSize:12}}>
                  <thead><tr><th>Centre</th><th>Title</th><th>Name</th><th>Age</th><th>Category</th><th>Language</th></tr></thead>
                  <tbody>
                    {preview.flatMap(r=>r.participants.map((p,i)=>(
                      <tr key={r.name+i}>
                        <td style={{color:"var(--muted)",fontSize:11}}>{r.code||r.name}</td>
                        <td>{p.title||"—"}</td>
                        <td style={{fontWeight:600}}>{p.name}</td>
                        <td>{p.age||"—"}</td>
                        <td>{getCategory(p.age)||"—"}</td>
                        <td>{p.language||"—"}</td>
                      </tr>
                    )))}
                  </tbody>
                </table>
              </SectionCard>
            </details>
          )}
        </>
      )}

      {/* Result */}
      {result && (
        <SectionCard style={{background:"#d1fae5",border:"1px solid #6ee7b7",marginBottom:12}}>
          <div style={{fontWeight:700,color:"#065f46",fontSize:15,marginBottom:6}}>✅ Import complete</div>
          <div style={{fontSize:13,color:"#047857",display:"flex",gap:20,flexWrap:"wrap"}}>
            <span>➕ {result.created} centre{result.created!==1?"s":""} created</span>
            <span>✏️ {result.updated} centre{result.updated!==1?"s":""} updated</span>
            <span>👥 {result.partTotal} participant{result.partTotal!==1?"s":""} imported</span>
          </div>
          <button className="btn btn-ghost btn-sm" style={{marginTop:10}} onClick={()=>{setResult(null);}}>Import another file</button>
        </SectionCard>
      )}
    </>
  );
}

// ══════════════════════════════════════════════════════════════════════════════
// BULK IMPORT PANEL
// ══════════════════════════════════════════════════════════════════════════════
function BulkImportPanel({ db, persist, toast$, centres }) {
  const [drag,setDrag]=useState(false);
  const [preview,setPreview]=useState(null);
  const [importing,setImporting]=useState(false);
  const [result,setResult]=useState(null);
  const fileRef=useRef();

  const parseFile=(file)=>{
    if(!file) return;
    const ext=file.name.split(".").pop().toLowerCase();
    const reader=new FileReader();
    reader.onload=(e)=>{
      try {
        let rows=[];
        if(ext==="csv"){ rows=e.target.result.split("\n").map(r=>r.split(",").map(c=>c.replace(/^"|"$/g,"").trim())); }
        else { const data=new Uint8Array(e.target.result), wb=window.XLSX.read(data,{type:"array"}); rows=window.XLSX.utils.sheet_to_json(wb.Sheets[wb.SheetNames[0]],{header:1,defval:""}); }
        if(rows.length<2){toast$("File is empty.","error");return;}
        processRows(rows);
      } catch(err){toast$("Parse error: "+err.message,"error");}
    };
    if(ext==="csv") reader.readAsText(file); else reader.readAsArrayBuffer(file);
  };

  const processRows=(rows)=>{
    const headers=rows[0].map(h=>String(h||"").toLowerCase().trim());
    const col=(...names)=>{ for(const n of names){ const i=headers.findIndex(h=>h.includes(n)); if(i>=0)return i; } return -1; };
    const iIntId=col("internal centre id","internal id","centre id");
    const iCode=col("centre code","code");
    const iRegNo=col("reg no","registration no","reg number");
    const iMarks=col("marks","score");
    const iRank=col("rank");
    const iPresent=col("present");
    const iAbsent=col("absent");
    const iCentreNo=col("centre number");
    // Track whether marks/rank/present/absent columns are present in the file at all
    const hasMarksCol=iMarks>=0;
    const hasRankCol=iRank>=0;
    const hasPresentCol=iPresent>=0;
    const hasAbsentCol=iAbsent>=0;
    // Reg No is now optional — rows without it can still update centre code
    const previewRows=[];
    for(let r=1;r<rows.length;r++){
      const row=rows[r];
      const intId=iIntId>=0?String(row[iIntId]||"").trim():"";
      const code=iCode>=0?String(row[iCode]||"").trim():"";
      const regNo=iRegNo>=0?String(row[iRegNo]||"").trim():"";
      // Use null sentinel to distinguish "column present but empty" from "column absent"
      const marks=hasMarksCol?(row[iMarks]===null||row[iMarks]===undefined||String(row[iMarks]).trim()===""?"":String(row[iMarks]).trim()):null;
      const rank=hasRankCol?(row[iRank]===null||row[iRank]===undefined||String(row[iRank]).trim()===""?"":String(row[iRank]).trim()):null;
      const presentVal=hasPresentCol?String(row[iPresent]||"").trim().toLowerCase():"";
      const absentVal=hasAbsentCol?String(row[iAbsent]||"").trim().toLowerCase():"";
      // Interpret truthy values: y, yes, 1, true, x
      const parseBool=(v)=>["y","yes","1","true","x"].includes(v);
      const present=hasPresentCol?parseBool(presentVal):null;
      const absent=hasAbsentCol?parseBool(absentVal):null;
      const centreNo=iCentreNo>=0?String(row[iCentreNo]||"").trim():"";
      // Skip rows with nothing useful
      if(!intId&&!code&&!centreNo) continue;
      let mc=null;
      if(intId) mc=centres.find(c=>String(c.internalId||"")===intId);
      if(!mc&&code) mc=centres.find(c=>(c.code||"").toLowerCase()===code.toLowerCase());
      if(!mc&&!centreNo) continue; // nothing to do for this row
      let mp=null, status="no_centre";
      if(mc){
        if(regNo){
          const parts=db.participants?.[mc.id]||[];
          mp=parts.find(p=>(p.regNo||"").toLowerCase()===regNo.toLowerCase());
          status=mp?"matched":"no_participant";
        } else {
          // No reg no — this row is for centre code update only
          status=centreNo?"centre_only":"no_centre";
        }
      }
      previewRows.push({regNo,intId,code,marks,rank,present,absent,hasMarksCol,hasRankCol,hasPresentCol,hasAbsentCol,centreNo,centreId:mc?.id||null,centreName:mc?.name||"Not Found",partId:mp?.id||null,partName:mp?`${mp.title} ${mp.name}`:"—",status});
    }
    if(!previewRows.length){toast$("No valid rows found.","error");return;}
    setPreview(previewRows);setResult(null);
  };

  const applyImport=async()=>{
    if(!preview) return;
    setImporting(true);
    let updated=0, skipped=0, centresUpdated=0;
    const newDb={...db,participants:{...db.participants},centres:{...db.centres}};

    // First pass: collect unique centre code updates (one per centreId)
    const codeUpdates={}; // centreId -> newCode
    for(const row of preview){
      if(row.centreNo&&row.centreId&&!codeUpdates[row.centreId]){
        codeUpdates[row.centreId]=row.centreNo.trim();
      }
    }

    // Apply centre code updates and reassign reg nos
    for(const [centreId, newCode] of Object.entries(codeUpdates)){
      const oldCode=newDb.centres[centreId]?.code||"";
      newDb.centres[centreId]={...newDb.centres[centreId],code:newCode};
      if(newCode!==oldCode && newDb.participants[centreId]){
        newDb.participants[centreId]=newDb.participants[centreId].map((p,i)=>{
          const existingRegNo=p.regNo||"";
          const suffix=existingRegNo.includes("-")?existingRegNo.split("-").pop():existingRegNo;
          const cleanSuffix=/^\d{3}$/.test(suffix)?suffix:String(i+1).padStart(3,"0");
          return {...p, regNo:newCode?`${newCode}-${cleanSuffix}`:cleanSuffix};
        });
      }
      centresUpdated++;
    }

    // Second pass: update participant marks/ranks
    for(const row of preview){
      if(row.status==="matched"&&row.centreId&&row.partId){
        newDb.participants[row.centreId]=(newDb.participants[row.centreId]||[]).map(p=>{
          if(p.id!==row.partId) return p;
          const updates={};
          // If column exists in file, always apply the value (even empty = clear)
          if(row.hasMarksCol) updates.marks=row.marks;
          if(row.hasRankCol)  updates.rank=row.rank;
          if(row.hasPresentCol) { updates.present=row.present; if(row.present) updates.absent=false; }
          if(row.hasAbsentCol)  { updates.absent=row.absent;   if(row.absent)  updates.present=false; }
          return {...p,...updates};
        });
        updated++;
      } else if(row.status!=="centre_only"){
        skipped++;
      }
    }

    await persist(newDb);
    setImporting(false);
    const parts=[];
    if(centresUpdated>0) parts.push(`${centresUpdated} centre code${centresUpdated!==1?"s":""} updated`);
    if(updated>0) parts.push(`${updated} participant${updated!==1?"s":""} updated`);
    if(skipped>0) parts.push(`${skipped} skipped`);
    toast$(parts.join(", ")||"Nothing to update.", (centresUpdated>0||updated>0)?"success":"warn");
    setResult({updated,skipped,centresUpdated});
  };

  const matchCount=preview?.filter(r=>r.status==="matched").length||0;
  const centreOnlyCount=preview?.filter(r=>r.status==="centre_only").length||0;
  const skipCount=preview?.filter(r=>r.status!=="matched"&&r.status!=="centre_only").length||0;

  return (
    <>
      <div className="page-title">Bulk Excel Import</div>
      <div className="page-sub">Upload Excel/CSV to bulk-update marks, ranks, attendance and centre code. When a Centre Number is provided, the centre's code is updated and all participant reg numbers are reassigned to use the new code.</div>
      <div style={{display:"grid",gridTemplateColumns:"repeat(auto-fit,minmax(260px,1fr))",gap:16,marginBottom:20}}>
        <SectionCard style={{borderColor:"#0d9488"}}>
          <div style={{fontSize:13,fontWeight:600,color:"var(--teal)",marginBottom:6}}>📄 Download Template</div>
          <div style={{fontSize:12,color:"var(--muted)",marginBottom:12}}>Get the Excel template with correct column headers</div>
          <button className="btn btn-teal btn-sm" onClick={downloadTemplate}>⬇️ Download Template</button>
        </SectionCard>
        <SectionCard>
          <div style={{fontSize:11,fontWeight:700,color:"var(--gold)",letterSpacing:.7,textTransform:"uppercase",marginBottom:10}}>Required Columns</div>
          <div style={{display:"flex",flexWrap:"wrap",gap:6}}>
            {["Internal Centre ID","Centre Code","Reg No.","Marks","Rank","Present","Absent","Centre Number (for admin)"].map(c=>(
              <span key={c} style={{background:"#dbeafe",color:"#1d4ed8",padding:"3px 10px",borderRadius:6,fontSize:11,fontWeight:600}}>{c}</span>
            ))}
          </div>
        </SectionCard>
      </div>
      {!preview
        ? <div className={`import-zone${drag?" drag":""}`}
            onDragOver={e=>{e.preventDefault();setDrag(true);}} onDragLeave={()=>setDrag(false)}
            onDrop={e=>{e.preventDefault();setDrag(false);const f=e.dataTransfer.files[0];if(f)parseFile(f);}}
            onClick={()=>fileRef.current?.click()}>
            <input ref={fileRef} type="file" accept=".xlsx,.xls,.csv" style={{display:"none"}}
              onChange={e=>{const f=e.target.files[0];if(f)parseFile(f);e.target.value="";}} />
            <div style={{fontSize:52,marginBottom:14}}>📥</div>
            <div style={{fontWeight:700,fontSize:16,color:"var(--text)",marginBottom:6}}>Drop Excel / CSV here</div>
            <div style={{fontSize:13,color:"var(--muted)"}}>or click to browse · .xlsx, .xls, .csv</div>
          </div>
        : <>
            <div style={{display:"flex",alignItems:"center",justifyContent:"space-between",marginBottom:14,flexWrap:"wrap",gap:10}}>
              <div style={{fontWeight:700,fontSize:15}}>Preview — {preview.length} rows</div>
              <div style={{display:"flex",gap:8}}>
                <span style={{background:"#d1fae5",color:"#065f46",padding:"4px 12px",borderRadius:8,fontSize:12,fontWeight:700}}>{matchCount} matched</span>
                {centreOnlyCount>0&&<span style={{background:"#dbeafe",color:"#1d4ed8",padding:"4px 12px",borderRadius:8,fontSize:12,fontWeight:700}}>{centreOnlyCount} code update{centreOnlyCount!==1?"s":""}</span>}
                {skipCount>0&&<span style={{background:"#fee2e2",color:"#991b1b",padding:"4px 12px",borderRadius:8,fontSize:12,fontWeight:700}}>{skipCount} skipped</span>}
              </div>
            </div>
            <SectionCard style={{padding:0,overflow:"auto",marginBottom:16}}>
              <table className="data-table" style={{minWidth:580}}>
                <thead><tr><th>Reg No.</th><th>Centre</th><th>Participant</th><th>Marks</th><th>Rank</th><th>Status</th></tr></thead>
                <tbody>
                  {preview.map((row,i)=>(
                    <tr key={i}>
                      <td style={{color:"var(--blue)",fontWeight:700,fontFamily:"monospace"}}>{row.regNo}</td>
                      <td style={{color:row.centreId?"var(--text)":"var(--red)"}}>{row.centreName}</td>
                      <td style={{color:row.partId?"var(--text)":"var(--muted)"}}>{row.partName}</td>
                      <td style={{color:"#38bdf8"}}>{row.marks===null?"(n/a)":row.marks===""?<span style={{color:"var(--red)",fontSize:11}}>clear</span>:row.marks}</td>
                      <td style={{color:"var(--gold)"}}>{row.rank===null?"(n/a)":row.rank===""?<span style={{color:"var(--red)",fontSize:11}}>clear</span>:row.rank}</td>
                      <td>{row.status==="matched"?<span style={{color:"var(--green)",fontWeight:700}}>✓ Update</span>:row.status==="centre_only"?<span style={{color:"#1d4ed8",fontWeight:700}}>🏷 Code update</span>:row.status==="no_participant"?<span style={{color:"var(--gold2)"}}>⚠ No match</span>:<span style={{color:"var(--red)"}}>✗ No centre</span>}</td>
                    </tr>
                  ))}
                </tbody>
              </table>
            </SectionCard>
            {result&&<div style={{background:(result.updated>0||result.centresUpdated>0)?"#d1fae5":"#fef3c7",borderRadius:10,padding:"12px 16px",marginBottom:14,fontSize:13,color:(result.updated>0||result.centresUpdated>0)?"#065f46":"#7d6608",fontWeight:600}}>
              {result.centresUpdated>0&&`✅ ${result.centresUpdated} centre code${result.centresUpdated!==1?"s":""} updated. `}
              {result.updated>0&&`✅ ${result.updated} participant${result.updated!==1?"s":""} updated. `}
              {result.skipped>0&&` ${result.skipped} skipped.`}
            </div>}
            <div style={{display:"flex",gap:10,flexWrap:"wrap"}}>
              <button className="btn btn-gold" onClick={applyImport} disabled={importing||( matchCount===0&&centreOnlyCount===0)}>
                {importing?"⏳ Importing…":`📥 Apply Import (${matchCount+centreOnlyCount} rows)`}
              </button>
              <button className="btn btn-ghost btn-sm" onClick={()=>{setPreview(null);setResult(null);}}>✕ Upload Different File</button>
            </div>
          </>
      }
    </>
  );
}

// ══════════════════════════════════════════════════════════════════════════════
// ADMIN STATUS PANEL
// ══════════════════════════════════════════════════════════════════════════════
function AdminStatusPanel({ db, persist, toast$, centres }) {
  const [selId,setSelId]=useState(null);
  const [newStatus,setNewStatus]=useState("draft");
  const [message,setMessage]=useState("");
  const [search,setSearch]=useState("");
  const isDesktop=useDesktop();

  const filtered=centres.filter(c=>(c.name||"").toLowerCase().includes(search.toLowerCase())||(c.spocUsername||"").toLowerCase().includes(search.toLowerCase()));
  const selCentre=selId?db.centres?.[selId]:null;
  const statusData=selId?db.centreStatuses?.[selId]:null;

  const postUpdate=async()=>{
    if(!selId)return;
    const prev=db.centreStatuses?.[selId]||{status:"draft",updates:[]};
    await persist({...db,centreStatuses:{...db.centreStatuses,[selId]:{status:newStatus,updates:[...prev.updates,{ts:new Date().toISOString(),newStatus,msg:message.trim()}]}}});
    toast$(`Updated for ${selCentre?.name}!`,"success");setMessage("");
  };

  const toggleAttendance=async()=>{
    await persist({...db,attendanceEnabled:!db.attendanceEnabled});
    toast$(db.attendanceEnabled?"Attendance collection disabled.":"Attendance collection enabled!","success");
  };

  if(selId&&selCentre){
    const {status="draft",updates=[]}=statusData||{}, opt=STATUS_OPTIONS.find(s=>s.value===status)||STATUS_OPTIONS[0];
    return (
      <div>
        <div style={{display:"flex",alignItems:"center",gap:10,marginBottom:20}}>
          <button className="btn btn-ghost btn-sm" onClick={()=>setSelId(null)}>← Back</button>
          <div>
            <div style={{fontFamily:"'Cinzel',serif",fontSize:15,fontWeight:700,color:"var(--gold)"}}>{selCentre.name}</div>
            {selCentre.code&&<span style={{fontSize:12,color:"var(--muted)"}}>Code: {selCentre.code}</span>}
          </div>
        </div>
        <div style={{display:"grid",gridTemplateColumns:isDesktop?"1fr 1fr":"1fr",gap:18}}>
          <div>
            <div style={{background:`linear-gradient(135deg,${opt.bg},var(--bg))`,border:`1px solid ${opt.color}40`,borderRadius:14,padding:"18px 20px",marginBottom:16,display:"flex",alignItems:"center",gap:14}}>
              <span style={{fontSize:32}}>{opt.icon}</span>
              <div>
                <div style={{fontSize:11,color:opt.color+"88",fontWeight:700,letterSpacing:.5,textTransform:"uppercase",marginBottom:3}}>Current Status</div>
                <div style={{fontFamily:"'Cinzel',serif",fontSize:18,fontWeight:700,color:opt.color}}>{opt.label}</div>
              </div>
            </div>
            <SectionCard title="Post Status Update">
              <div style={{display:"flex",flexDirection:"column",gap:8,marginBottom:14}}>
                {STATUS_OPTIONS.filter(o=>!o.spocSet).map(o=>(
                  <button key={o.value} onClick={()=>setNewStatus(o.value)}
                    style={{padding:"10px 14px",borderRadius:9,border:`2px solid ${newStatus===o.value?o.color:"var(--border)"}`,
                      background:newStatus===o.value?o.bg:"transparent",color:newStatus===o.value?o.color:"var(--muted)",
                      cursor:"pointer",fontFamily:"'Outfit',sans-serif",fontWeight:600,fontSize:12,textAlign:"left",
                      display:"flex",alignItems:"center",gap:8,transition:"all .15s",WebkitTapHighlightColor:"transparent"}}>
                    <span style={{fontSize:16}}>{o.icon}</span>{o.label}
                  </button>
                ))}
              </div>
              <Field label="Message to SPOC (optional)" style={{marginBottom:14}}>
                <textarea className="inp" rows={3} value={message} onChange={e=>setMessage(e.target.value)}
                  placeholder="e.g. Question papers dispatched by speed post." style={{minHeight:80}} />
              </Field>
              <button className="btn btn-gold btn-full" onClick={postUpdate}>📢 Post Update</button>
            </SectionCard>
          </div>
          <div>
            {updates.length>0&&(
              <>
                <div style={{display:"flex",alignItems:"center",justifyContent:"space-between",marginBottom:12}}>
                  <div style={{fontSize:11,color:"var(--muted)",fontWeight:700,letterSpacing:.5,textTransform:"uppercase"}}>History ({updates.length})</div>
                  <button className="btn btn-danger" style={{padding:"5px 10px",fontSize:11}}
                    onClick={async()=>{if(window.confirm("Clear history?")){const cs={...db.centreStatuses};delete cs[selId];await persist({...db,centreStatuses:cs});toast$("Cleared.","info");setSelId(null);}}}>
                    Clear All
                  </button>
                </div>
                <div style={{display:"flex",flexDirection:"column",gap:8}}>
                  {[...updates].reverse().map((u,i)=>(
                    <SectionCard key={i} style={{marginBottom:0}}>
                      <div style={{display:"flex",alignItems:"center",justifyContent:"space-between",marginBottom:u.msg?8:0,gap:8,flexWrap:"wrap"}}>
                        <StatusBadge value={u.newStatus} />
                        <div style={{fontSize:11,color:"var(--subtle)"}}>{new Date(u.ts).toLocaleString("en-IN",{day:"numeric",month:"short",hour:"2-digit",minute:"2-digit"})}</div>
                      </div>
                      {u.msg&&<div style={{fontSize:13,color:"var(--text)",lineHeight:1.6,whiteSpace:"pre-wrap"}}>{u.msg}</div>}
                    </SectionCard>
                  ))}
                </div>
              </>
            )}
          </div>
        </div>
      </div>
    );
  }

  return (
    <>
      <div style={{display:"flex",alignItems:"center",justifyContent:"space-between",marginBottom:16,flexWrap:"wrap",gap:10}}>
        <div className="page-title" style={{marginBottom:0}}>Centre Status</div>
        <div style={{display:"flex",alignItems:"center",gap:12}}>
          <span style={{fontSize:12,color:"var(--muted)",fontWeight:600}}>Attendance Collection</span>
          <button onClick={toggleAttendance}
            style={{width:48,height:26,borderRadius:13,border:"none",cursor:"pointer",transition:"all .2s",
              background:db.attendanceEnabled?"#059669":"#cbd5e1",position:"relative",flexShrink:0}}>
            <span style={{position:"absolute",top:3,left:db.attendanceEnabled?24:3,width:20,height:20,
              borderRadius:"50%",background:"#fff",transition:"all .2s",boxShadow:"0 1px 3px #0003"}} />
          </button>
          <span style={{fontSize:11,fontWeight:700,color:db.attendanceEnabled?"#059669":"var(--muted)"}}>
            {db.attendanceEnabled?"ON":"OFF"}
          </span>
        </div>
      </div>
      <div style={{display:"flex",flexWrap:"wrap",gap:6,marginBottom:16}}>
        {STATUS_OPTIONS.map(o=>{
          const count=centres.filter(c=>(db.centreStatuses?.[c.id]?.status||"draft")===o.value).length;
          if(!count) return null;
          return <span key={o.value} style={{background:o.bg,color:o.color,padding:"4px 11px",borderRadius:16,fontSize:11,fontWeight:700}}>{o.icon} {o.label}: {count}</span>;
        })}
      </div>
      <div style={{position:"relative",marginBottom:14}}>
        <svg style={{position:"absolute",left:13,top:"50%",transform:"translateY(-50%)",opacity:.4}} width="14" height="14" viewBox="0 0 24 24" fill="none" stroke="#94a3b8" strokeWidth="2">
          <circle cx="11" cy="11" r="8"/><path d="m21 21-4.35-4.35"/>
        </svg>
        <input className="inp" style={{paddingLeft:38}} placeholder="Search centres…" value={search} onChange={e=>setSearch(e.target.value)} />
      </div>
      {filtered.length===0
        ? <div style={{textAlign:"center",padding:"60px",color:"var(--subtle)"}}><div style={{fontSize:48,marginBottom:14}}>🔔</div><div style={{fontWeight:600}}>No centres yet</div></div>
        : isDesktop
          ? <SectionCard style={{padding:0,overflow:"hidden"}}>
              <table className="data-table">
                <thead><tr><th>Centre</th><th>Code</th><th>Status</th><th>Last Update</th><th>Action</th></tr></thead>
                <tbody>
                  {filtered.map(c=>{
                    const sd=db.centreStatuses?.[c.id], status=sd?.status||"draft", last=(sd?.updates||[]).slice(-1)[0];
                    return (
                      <tr key={c.id} className="row-h" style={{cursor:"pointer"}} onClick={()=>{setSelId(c.id);setNewStatus(status);setMessage("");}}>
                        <td><div style={{fontWeight:600}}>{c.name}</div><div style={{fontSize:11,color:"var(--muted)"}}>@{c.spocUsername}</div></td>
                        <td>{c.code?<span style={{background:"#dbeafe",color:"#1d4ed8",padding:"2px 8px",borderRadius:5,fontSize:11,fontWeight:700}}>{c.code}</span>:"—"}</td>
                        <td><StatusBadge value={status} /></td>
                        <td style={{fontSize:12,color:"var(--subtle)"}}>{last?new Date(last.ts).toLocaleString("en-IN",{day:"numeric",month:"short",hour:"2-digit",minute:"2-digit"}):"—"}</td>
                        <td><span style={{color:"var(--gold)",fontWeight:600}}>Update ›</span></td>
                      </tr>
                    );
                  })}
                </tbody>
              </table>
            </SectionCard>
          : filtered.map(c=>{
              const sd=db.centreStatuses?.[c.id], status=sd?.status||"draft", updates=sd?.updates||[], last=updates.slice(-1)[0];
              return (
                <div key={c.id} style={{background:"var(--surface)",border:"1px solid var(--border)",borderRadius:12,padding:"14px 16px",marginBottom:8,cursor:"pointer"}} className="row-h"
                  onClick={()=>{setSelId(c.id);setNewStatus(status);setMessage("");}}>
                  <div style={{display:"flex",alignItems:"flex-start",justifyContent:"space-between",marginBottom:8,gap:8}}>
                    <div>
                      <div style={{display:"flex",alignItems:"center",gap:6,flexWrap:"wrap"}}>
                        <div style={{fontWeight:600,fontSize:14}}>{c.name}</div>
                        {c.code&&<span style={{background:"#dbeafe",color:"#1d4ed8",padding:"2px 8px",borderRadius:5,fontSize:11,fontWeight:700}}>{c.code}</span>}
                      </div>
                      <div style={{fontSize:12,color:"var(--muted)"}}>@{c.spocUsername}</div>
                    </div>
                    <StatusBadge value={status} />
                  </div>
                  <div style={{fontSize:12,color:"var(--subtle)",borderTop:"1px solid var(--border2)",paddingTop:8}}>
                    {last?`Last: ${new Date(last.ts).toLocaleString("en-IN",{day:"numeric",month:"short",hour:"2-digit",minute:"2-digit"})}${last.msg?` — "${last.msg.slice(0,45)}…"`:""}` :"No updates yet — tap to set status"}
                  </div>
                </div>
              );
            })
      }
    </>
  );
}
